        [
            browser, "--headless=new", "--disable-gpu", "--no-sandbox",
            f"--user-data-dir={tmp_path / 'chrome-profile'}", "--virtual-time-budget=1000",
            "--dump-dom", report_path.as_uri(),
        ],
        stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True,
